import { Problem } from '../types/index.ts';

// Helper to create LeetCode SQL 50 problem
function createLeetCodeSql50(
  number: number,
  title: string,
  slug: string,
  difficulty: 'Easy' | 'Medium' | 'Hard',
  topic: string,
  pattern: string
): Problem {
  return {
    id: `sql-50-${number}`,
    title: `${number}. ${title}`,
    difficulty,
    topic,
    pattern,
    leetcodeSlug: slug,
    leetcodeUrl: `https://leetcode.com/problems/${slug}/`,
    leetcodeVerified: true,
    gfgUrl: `https://www.geeksforgeeks.org/?s=${encodeURIComponent(title + ' SQL')}`,
    gfgVerified: false,
    lastVerifiedDate: '2026-08-15',
    sqlMeta: {
      dialect: 'Multi-dialect',
      module: 'SQL Fundamentals',
      taskStatement: `Solve LeetCode problem #${number}: ${title}. Write a query to produce the requested outcome according to LeetCode schema specifications.`,
      sampleQueryOrSolution: `-- Solution pattern for ${title}\nSELECT ...`,
    },
  };
}

