// Helper to create Data Analyst SQL 100 problem
function createAnalystSql(
  idx: number,
  title: string,
  module:
    | 'SQL Fundamentals'
    | 'Joins & Relational Logic'
    | 'Aggregation & Business Metrics'
    | 'Window Functions'
    | 'CTEs, Subqueries & Advanced'
    | 'Data Quality & Analytics Cases'
    | 'Dashboard-Ready Case Studies',
  difficulty: 'Easy' | 'Medium' | 'Hard',
  taskStatement: string,
  expectedSchema: string,
  sampleQueryOrSolution: string,
  expectedOutputSample: string,
  dialect: 'PostgreSQL' | 'MySQL' = 'PostgreSQL'
): Problem {
  const pad = String(idx).padStart(3, '0');
  const searchUrl = `https://leetcode.com/problemset/database/?search=${encodeURIComponent(title)}`;
  return {
    id: `analyst-sql-${pad}`,
    title: `${pad}. ${title}`,
    difficulty,
    topic: `SQL: ${module}`,
    pattern: module,
    leetcodeUrl: searchUrl,
    leetcodeVerified: false, // Search link clearly marked as per blueprint contract
    gfgUrl: `https://www.geeksforgeeks.org/?s=${encodeURIComponent(title + ' SQL')}`,
    gfgVerified: false,
    lastVerifiedDate: '2026-08-15',
    sqlMeta: {
      dialect,
      module,
      taskStatement,
      expectedSchema,
      sampleQueryOrSolution,
      expectedOutputSample,
    },
  };
}

